// ==========================================
// CONFIGURATION PARAMETERS
// ==========================================
const GRID_SIZE = 20;
const RADIUS_METERS = 100;
const BUFFER_METERS = 50;

// ==========================================
// DATA CLEANING - ROBUST VERSION
// ==========================================

function cleanAndNormalizeLat(lat) {
  // Convert to string and remove all separators
  let cleaned = String(lat).replace(/[.,\s]/g, '');

  // Ensure it's the right length (16 digits for lat)
  if (cleaned.length < 16) {
    cleaned = cleaned.padEnd(16, '0');  // Pad with zeros if too short
  } else if (cleaned.length > 16) {
    cleaned = cleaned.slice(0, 16);  // Trim if too long
  }

  const num = parseFloat(cleaned);
  return num / 100000000000000;  // Divide by 10^14
}

function cleanAndNormalizeLong(long) {
  // Convert to string and remove all separators
  let cleaned = String(long).replace(/[.,\s]/g, '');

  // Ensure it's the right length (17 digits for long)
  if (cleaned.length < 17) {
    cleaned = cleaned.padEnd(17, '0');  // Pad with zeros if too short
  } else if (cleaned.length > 17) {
    cleaned = cleaned.slice(0, 17);  // Trim if too long
  }

  const num = parseFloat(cleaned);
  return num / 1000000000000000;  // Divide by 10^15
}

// ==========================================
// CODE STARTS HERE
// ==========================================

const observations = $input.all();

// Haversine distance in meters
function haversineDistance(lat1, lon1, lat2, lon2) {
  const R = 6371000;
  const φ1 = lat1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const Δφ = (lat2 - lat1) * Math.PI / 180;
  const Δλ = (lon2 - lon1) * Math.PI / 180;

  const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) +
          Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ/2) * Math.sin(Δλ/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
}

// Shannon diversity index
function calculateShannon(speciesCounts) {
  const total = Object.values(speciesCounts).reduce((a, b) => a + b, 0);
  if (total === 0) return 0;

  let shannon = 0;
  for (const count of Object.values(speciesCounts)) {
    if (count > 0) {
      const p = count / total;
      shannon -= p * Math.log(p);
    }
  }
  return shannon;
}

// Simple meter-to-degree conversion
function metersToLatDegrees(meters) {
  return meters / 111320;
}

function metersToLonDegrees(meters, latitude) {
  return meters / (111320 * Math.cos(latitude * Math.PI / 180));
}

// Normalize observations with robust cleaning
const normalizedObs = observations.map(obs => ({
  ...obs.json,
  lat: cleanAndNormalizeLat(obs.json.lat),
  long: cleanAndNormalizeLong(obs.json.long)
}));

// Calculate bounding box
let minLat = Math.min(...normalizedObs.map(o => o.lat));
let maxLat = Math.max(...normalizedObs.map(o => o.lat));
let minLon = Math.min(...normalizedObs.map(o => o.long));
let maxLon = Math.max(...normalizedObs.map(o => o.long));

// Add buffer
const centerLat = (minLat + maxLat) / 2;
const latBuffer = metersToLatDegrees(BUFFER_METERS);
const lonBuffer = metersToLonDegrees(BUFFER_METERS, centerLat);

const buffered = {
  minLat: minLat - latBuffer,
  maxLat: maxLat + latBuffer,
  minLon: minLon - lonBuffer,
  maxLon: maxLon + lonBuffer
};

// Generate grid
const gridPoints = [];
for (let i = 0; i < GRID_SIZE; i++) {
  for (let j = 0; j < GRID_SIZE; j++) {
    const lat = buffered.minLat + (buffered.maxLat - buffered.minLat) * i / (GRID_SIZE - 1);
    const lon = buffered.minLon + (buffered.maxLon - buffered.minLon) * j / (GRID_SIZE - 1);

    const nearbyObs = normalizedObs.filter(obs => 
      haversineDistance(lat, lon, obs.lat, obs.long) <= RADIUS_METERS
    );

    const speciesCounts = {};
    nearbyObs.forEach(obs => {
      speciesCounts[obs.species_guess] = (speciesCounts[obs.species_guess] || 0) + 1;
    });

    gridPoints.push({
      lat,
      long: lon,
      species_richness: Object.keys(speciesCounts).length,
      shannon_index: Number(calculateShannon(speciesCounts).toFixed(3)),
      total_observations: nearbyObs.length,
      grid_i: i,
      grid_j: j
    });
  }
}

return [{
  json: {
    metadata: {
      grid_size: GRID_SIZE,
      radius_meters: RADIUS_METERS,
      buffer_meters: BUFFER_METERS,
      total_grid_points: gridPoints.length,
      total_observations: normalizedObs.length,
      bounding_box: buffered
    },
    grid_points: gridPoints,
    observations: normalizedObs
  }
}];
